+/**
+ * 创建一个防抖函数：在最后一次调用后延迟 wait 毫秒再执行。
+ *
+ * @param fn 待防抖的函数
+ * @param wait 等待毫秒数，默认 300
+ */
+export function debounce<T extends (...args: any[]) => void>(
+  fn: T,
+  wait = 300,
+): (...args: Parameters<T>) => void {
+  let timer: ReturnType<typeof setTimeout> | null = null;
+  return (...args: Parameters<T>) => {
+    if (timer) {
+      clearTimeout(timer);
+    }
+    timer = setTimeout(() => {
+      fn(...args);
+      timer = null;
+    }, wait);
+  };
+}
